// Match film on YouTube, by bout and by dual.
//
// matchVideos.json is generated by reel-tools (`reel.py --team HighSchool
// site-videos`) from the Match Playlists: each video's title names the
// wrestler and the order at the event, which lines it up with a bout. Rerun it
// and commit the file after new film goes up.
import matchVideos from './matchVideos.json';

/** The YouTube ids of a bout's video, in part order (most bouts have one). */
export const videoIdsFor = (matchId) => matchVideos.bouts[matchId] || [];

/** The YouTube playlist that holds every bout of a dual, if one was filmed. */
export const playlistIdFor = (teamMatchId) => matchVideos.duals[teamMatchId] || null;

export const watchUrl = (videoId) => `https://www.youtube.com/watch?v=${videoId}`;

export const playlistUrl = (playlistId) => `https://www.youtube.com/playlist?list=${playlistId}`;
